INSERT INTO `znl_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(1426, 177, '_home_banner_sub_heading', 'field_59f4eb606b25e'),
(1427, 177, 'home_banner_notes_beside_the_countdown', 'Arcona Token Sale: 1 USD = 1 arcona\r\nArcona token will be used for the purchase of all digital goods and services within the ecosystem.'),
(1428, 177, '_home_banner_notes_beside_the_countdown', 'field_59f4eb726b25f'),
(1429, 177, 'home_banner_subscribe_button_title', 'SUBSCRIBE WHITELIST'),
(1430, 177, '_home_banner_subscribe_button_title', 'field_59f4ebd36b260'),
(1431, 177, 'h_sec1_heading', 'AUGMENTED REALITY ECOSYSTEM'),
(1432, 177, '_h_sec1_heading', 'field_59f4f653924fb'),
(1433, 177, 'h_sec1_text_content', 'The Arcona Ecosystem creates a Digital Land - a layer of Augmented Reality uniting the physical and virtual worlds into a single information environment perfectly linked to our real world. It is designed for everyday user interactive experience with augmented, virtual and mixed reality multimedia content in real world locations.'),
(1434, 177, '_h_sec1_text_content', 'field_59f4f66e924fc'),
(1435, 177, 'h_sec1_link_for_the_text_content', 'https://www.arcona.io/'),
(1436, 177, '_h_sec1_link_for_the_text_content', 'field_59f4f6a2924fd'),
(1437, 177, 'h_sec1_youtube_video_embedcode', '<iframe height=\"100%\" width=\"100%\" allowfullscreen=\"\" frameborder=\"0\" title=\"External YouTube\" src=\"//www.youtube.com/embed/s0ERldL5hEE?wmode=transparent&amp;autoplay=0&amp;theme=dark&amp;controls=0&amp;autohide=0&amp;loop=1&amp;showinfo=0&amp;rel=0&amp;playlist=s0ERldL5hEE&amp;enablejsapi=0\"></iframe>'),
(1438, 177, '_h_sec1_youtube_video_embedcode', 'field_59f4f6b2924fe'),
(1439, 177, 'h_sec2_heading', 'AR ECOSYSTEM MAIN FEATURES'),
(1440, 177, '_h_sec2_heading', 'field_59f4fb467be91'),
(1441, 177, 'h_sec2_column_content_0_image', '92'),
(1442, 177, '_h_sec2_column_content_0_image', 'field_59f4fb817be93'),
(1443, 177, 'h_sec2_column_content_0_title', 'SETUP REMOTELY'),
(1444, 177, '_h_sec2_column_content_0_title', 'field_59f4fba67be94'),
(1445, 177, 'h_sec2_column_content_0_description', 'Arcona allows you to place virtual projects anywhere in the world without leaving your home. Choose the most popular and visited places. Create whole worlds on your Digital land'),
(1446, 177, '_h_sec2_column_content_0_description', 'field_59f4fbb87be95'),
(1447, 177, 'h_sec2_column_content_1_image', '94'),
(1448, 177, '_h_sec2_column_content_1_image', 'field_59f4fb817be93'),
(1449, 177, 'h_sec2_column_content_1_title', 'BUILD AND TRADE'),
(1450, 177, '_h_sec2_column_content_1_title', 'field_59f4fba67be94'),
(1451, 177, 'h_sec2_column_content_1_description', 'The world market is open to you in the Arcona ecosystem. Buy, sell, rent out your Digital Land. Make money on creativity, creating and selling the most incredible content.'),
(1452, 177, '_h_sec2_column_content_1_description', 'field_59f4fbb87be95'),
(1453, 177, 'h_sec2_column_content_2_image', '93'),
(1454, 177, '_h_sec2_column_content_2_image', 'field_59f4fb817be93'),
(1455, 177, 'h_sec2_column_content_2_title', 'SAFE PROPERTY'),
(1456, 177, '_h_sec2_column_content_2_title', 'field_59f4fba67be94'),
(1457, 177, 'h_sec2_column_content_2_description', 'Smart contract on blockсhain, guarantees protection of copyright and property rights. The system automates royalty payments to content creators, and rents to digital asset owners'),
(1458, 177, '_h_sec2_column_content_2_description', 'field_59f4fbb87be95'),
(1459, 177, 'h_sec2_column_content', '3'),
(1460, 177, '_h_sec2_column_content', 'field_59f4fb567be92'),
(1461, 177, 'h_sec3_heading', 'YOUR DIGITAL LANDS'),
(1462, 177, '_h_sec3_heading', 'field_59f501a31d0e4'),
(1463, 177, 'h_sec3_image', '101'),
(1464, 177, '_h_sec3_image', 'field_59f501b51d0e5'),
(1465, 177, 'h_sec3_text_content', 'Digital land is the main asset of the Arcona ecosystem, built on the principles of blockchain. The rules of land use are described in the Ethereum smart contract. You can buy your own lot in exchange for an ERC20 standard token - arcon.\r\n\r\nWhy should you buy digital land? Owning a lot of Digital Land is an interesting experience for a creative person and a profitable business for business people. You can change the world on the lawn in front of your house or create serious commercial project thousands of kilometers away from you, on another continent.\r\n\r\nYour land - your rules. Each lot of the digital land is associated with a specific location in the physical world. This is a place where you will be attracting many people to share with them the results of your work.\r\n\r\nOrganize events, shows and presentations, create games, open virtual stores. Digital land is your property, organize it to your taste.\r\n\r\nYou absolutely need Digital Land if you want to create augmented reality online projects anywhere on the planet.'),
(1466, 177, '_h_sec3_text_content', 'field_59f501c91d0e6'),
(1467, 177, 'h_sec4_heading', 'ARCONA ECOSYSTEM'),
(1468, 177, '_h_sec4_heading', 'field_59f503ac089e2'),
(1469, 177, 'h_sec4_image', '107'),
(1470, 177, '_h_sec4_image', 'field_59f503c4089e3'),
(1471, 177, 'h_sec5_heading', 'ARCONA TOKEN SALE'),
(1472, 177, '_h_sec5_heading', 'field_59f5069450063'),
(1473, 177, 'h_sec5_text_content', '<p class=\"type1\">Arcona will be introduced in the first quarter of 2018</p>\r\n<p class=\"type2\">The arcona token help you to purchase digital lands and other digital assets.</p>\r\n<p class=\"type2\">You can get arcona as a reward for performing tasks set by the Arcona system.</p>\r\n<p class=\"type3\">Total emission — 100 000 000 arconas</p>\r\n<p class=\"type4\">DISTRIBUTION OF TOKENS</p>'),
(1474, 177, '_h_sec5_text_content', 'field_59f506dd50064'),
(1475, 177, 'h_sec5_image', '115'),
(1476, 177, '_h_sec5_image', 'field_59f5074750065'),
(1477, 177, 'h_sec6_heading', 'WHO IF NOT US?'),
(1478, 177, '_h_sec6_heading', 'field_59f5ab312cd86'),
(1479, 177, 'h_sec6_image', '158'),
(1480, 177, '_h_sec6_image', 'field_59f5ab5b2cd87'),
(1481, 177, 'h_sec6_top_text_content', 'The Arcona platform is being developed by the professional team of PiligrimXXI. We became the first Russian IT start-up operating in the international augmented reality market in the travel industry.\r\n\r\nWe have given tourists the opportunity to combine real travel and time travel. Using a smartphone and AR headset, travelers can see with their own eyes the vanished architectural wonders of the past and witness historical events in real time and space.\r\n\r\nIn 2014, Piligrim XXI launched the world\'s first outdoor augmented reality park, and today a network of 8 such parks with a total area of 7,700 ar operates in 6 countries.\r\n\r\nSince 2015, PiligrimXXI has been actively investing its own funds in research in the field of distributed GIS system, Augmented Reality technologies, 3D simulations, Computer vision and Artificial Intelligence.\r\n\r\nWe are launching an ITO in order to start the process of generating Digital Land as early as 2019. The first digitized territories will appear in the 10 largest cities in the world - New York, London, Paris, Tokyo, Beijing, Rome, Mexico, St. Petersburg, Istanbul and Barcelona.\r\n\r\nBut even before the launch of the platform, in the first half of 2018, we will be publicly releasing our ARViewer and a Marketplace where everybody will be able to use arcon tokens for payments.'),
