(4476, 221, '_home_banner_subscribe_button_title', 'field_59f4ebd36b260'),
(4477, 221, 'h_sec1_heading', 'AUGMENTED REALITY ECOSYSTEM'),
(4478, 221, '_h_sec1_heading', 'field_59f4f653924fb'),
(4479, 221, 'h_sec1_text_content', 'The Arcona Ecosystem creates a Digital Land - a layer of Augmented Reality uniting the physical and virtual worlds into a single information environment perfectly linked to our real world. It is designed for everyday user interactive experience with augmented, virtual and mixed reality multimedia content in real world locations.'),
(4480, 221, '_h_sec1_text_content', 'field_59f4f66e924fc'),
