(5121, 222, 'h_sec7_heading', 'ROAD MAP'),
(5122, 222, '_h_sec7_heading', 'field_59f50a7113a0f'),
(5123, 222, 'h_sec7_road_map_0_year', '2014'),
(5124, 222, '_h_sec7_road_map_0_year', 'field_59f50a9613a11'),
(5125, 222, 'h_sec7_road_map_0_open_or_close', '1'),
(5126, 222, '_h_sec7_road_map_0_open_or_close', 'field_59f50b06ae597'),
(5127, 222, 'h_sec7_road_map_0_description', 'Launched first outdoor AR park - \"Ludza Castle.\" It increased by 30% the flow of tourists in the region, attracting more than 60,000 tourists/year. Microsoft Seed Fund grant, Accelerations: Intel, Google, Faber Novel. Top 50  russian  startups with  highest rating AAA'),
(5128, 222, '_h_sec7_road_map_0_description', 'field_59f50aaa13a12'),
(5129, 222, 'h_sec7_road_map_1_year', '2015'),
(5130, 222, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(5131, 222, 'h_sec7_road_map_1_open_or_close', '1'),
(5132, 222, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(5133, 222, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(5134, 222, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(5135, 222, 'h_sec7_road_map_2_year', '2016'),
