(5475, 227, 'home_banner_heading', 'Augmented Reality World Discovered'),
(5476, 227, '_home_banner_heading', 'field_59f4eb4e6b25d'),
(5477, 227, 'home_banner_sub_heading', 'Become the Owner of<br>the Digital Land'),
(5478, 227, '_home_banner_sub_heading', 'field_59f4eb606b25e'),
(5479, 227, 'home_banner_notes_beside_the_countdown', 'Arcona Token Sale: 1 USD = 1 arcona\r\nArcona token will be used for the purchase of all digital goods and services within the ecosystem.'),
(5480, 227, '_home_banner_notes_beside_the_countdown', 'field_59f4eb726b25f'),
(5481, 227, 'home_banner_subscribe_button_title', 'SUBSCRIBE WHITELIST'),
(5482, 227, '_home_banner_subscribe_button_title', 'field_59f4ebd36b260'),
(5483, 227, 'h_sec1_heading', 'AUGMENTED REALITY ECOSYSTEM'),
(5484, 227, '_h_sec1_heading', 'field_59f4f653924fb'),
(5485, 227, 'h_sec1_text_content', 'The Arcona Ecosystem creates a Digital Land - a layer of Augmented Reality uniting the physical and virtual worlds into a single information environment perfectly linked to our real world. It is designed for everyday user interactive experience with augmented, virtual and mixed reality multimedia content in real world locations.'),
(5486, 227, '_h_sec1_text_content', 'field_59f4f66e924fc'),
(5487, 227, 'h_sec1_link_for_the_text_content', 'https://www.arcona.io/'),
(5488, 227, '_h_sec1_link_for_the_text_content', 'field_59f4f6a2924fd'),
(5489, 227, 'h_sec1_youtube_video_embedcode', '<iframe height=\"100%\" width=\"100%\" allowfullscreen=\"\" frameborder=\"0\" title=\"External YouTube\" src=\"//www.youtube.com/embed/s0ERldL5hEE?wmode=transparent&amp;autoplay=0&amp;theme=dark&amp;controls=0&amp;autohide=0&amp;loop=1&amp;showinfo=0&amp;rel=0&amp;playlist=s0ERldL5hEE&amp;enablejsapi=0\"></iframe>'),
(5490, 227, '_h_sec1_youtube_video_embedcode', 'field_59f4f6b2924fe'),
(5491, 227, 'h_sec2_heading', 'AR ECOSYSTEM MAIN FEATURES'),
(5492, 227, '_h_sec2_heading', 'field_59f4fb467be91'),
(5493, 227, 'h_sec2_column_content_0_image', '92'),
(5494, 227, '_h_sec2_column_content_0_image', 'field_59f4fb817be93'),
(5495, 227, 'h_sec2_column_content_0_title', 'SETUP REMOTELY'),
(5496, 227, '_h_sec2_column_content_0_title', 'field_59f4fba67be94'),
(5497, 227, 'h_sec2_column_content_0_description', 'Arcona allows you to place virtual projects anywhere in the world without leaving your home. Choose the most popular and visited places. Create whole worlds on your Digital land'),
(5498, 227, '_h_sec2_column_content_0_description', 'field_59f4fbb87be95'),
(5499, 227, 'h_sec2_column_content_1_image', '94'),
(5500, 227, '_h_sec2_column_content_1_image', 'field_59f4fb817be93'),
(5501, 227, 'h_sec2_column_content_1_title', 'BUILD AND TRADE'),
(5502, 227, '_h_sec2_column_content_1_title', 'field_59f4fba67be94'),
(5503, 227, 'h_sec2_column_content_1_description', 'The world market is open to you in the Arcona ecosystem. Buy, sell, rent out your Digital Land. Make money on creativity, creating and selling the most incredible content.'),
(5504, 227, '_h_sec2_column_content_1_description', 'field_59f4fbb87be95'),
(5505, 227, 'h_sec2_column_content_2_image', '93'),
(5506, 227, '_h_sec2_column_content_2_image', 'field_59f4fb817be93'),
(5507, 227, 'h_sec2_column_content_2_title', 'SAFE PROPERTY'),
(5508, 227, '_h_sec2_column_content_2_title', 'field_59f4fba67be94'),
(5509, 227, 'h_sec2_column_content_2_description', 'Smart contract on blockсhain, guarantees protection of copyright and property rights. The system automates royalty payments to content creators, and rents to digital asset owners'),
(5510, 227, '_h_sec2_column_content_2_description', 'field_59f4fbb87be95'),
(5511, 227, 'h_sec2_column_content', '3'),
(5512, 227, '_h_sec2_column_content', 'field_59f4fb567be92'),
(5513, 227, 'h_sec3_heading', 'YOUR DIGITAL LANDS'),
(5514, 227, '_h_sec3_heading', 'field_59f501a31d0e4'),
(5515, 227, 'h_sec3_image', '101'),
(5516, 227, '_h_sec3_image', 'field_59f501b51d0e5'),
(5517, 227, 'h_sec3_text_content', 'Digital land is the main asset of the Arcona ecosystem, built on the principles of blockchain. The rules of land use are described in the Ethereum smart contract. You can buy your own lot in exchange for an ERC20 standard token - arcon.\r\n\r\nWhy should you buy digital land? Owning a lot of Digital Land is an interesting experience for a creative person and a profitable business for business people. You can change the world on the lawn in front of your house or create serious commercial project thousands of kilometers away from you, on another continent.\r\n\r\nYour land - your rules. Each lot of the digital land is associated with a specific location in the physical world. This is a place where you will be attracting many people to share with them the results of your work.\r\n\r\nOrganize events, shows and presentations, create games, open virtual stores. Digital land is your property, organize it to your taste.\r\n\r\nYou absolutely need Digital Land if you want to create augmented reality online projects anywhere on the planet.'),
(5518, 227, '_h_sec3_text_content', 'field_59f501c91d0e6'),
(5519, 227, 'h_sec4_heading', 'ARCONA ECOSYSTEM'),
(5520, 227, '_h_sec4_heading', 'field_59f503ac089e2'),
(5521, 227, 'h_sec4_image', '107'),
(5522, 227, '_h_sec4_image', 'field_59f503c4089e3'),
(5523, 227, 'h_sec5_heading', 'ARCONA TOKEN SALE'),
(5524, 227, '_h_sec5_heading', 'field_59f5069450063'),
(5525, 227, 'h_sec5_text_content', '<p class=\"type1\">Arcona will be introduced in the first quarter of 2018</p>\r\n<p class=\"type2\">The arcona token help you to purchase digital lands and other digital assets.</p>\r\n<p class=\"type2\">You can get arcona as a reward for performing tasks set by the Arcona system.</p>\r\n<p class=\"type3\">Total emission — 100 000 000 arconas</p>\r\n<p class=\"type4\">DISTRIBUTION OF TOKENS</p>'),
(5526, 227, '_h_sec5_text_content', 'field_59f506dd50064'),
(5527, 227, 'h_sec5_image', '115'),
(5528, 227, '_h_sec5_image', 'field_59f5074750065'),
