(7082, 235, 'h_sec6_top_sponsors', '5'),
(7083, 235, '_h_sec6_top_sponsors', 'field_59f5abab2cd89'),
(7084, 235, 'h_sec6_text_below_sponsors', 'Microsoft Seed Fund grant, accelerations of Intel and Google, Skolkovo Foundation,\r\ntop 20 startups by Booking Booster Programm assisted in our job.'),
(7085, 235, '_h_sec6_text_below_sponsors', 'field_59f5ac0c2cd8c'),
