(7525, 236, '_home_banner_subscribe_button_title', 'field_59f4ebd36b260'),
(7526, 236, 'h_sec1_heading', 'AUGMENTED REALITY ECOSYSTEM'),
(7527, 236, '_h_sec1_heading', 'field_59f4f653924fb'),
(7528, 236, 'h_sec1_text_content', 'The Arcona Ecosystem creates a Digital Land - a layer of Augmented Reality uniting the physical and virtual worlds into a single information environment perfectly linked to our real world. It is designed for everyday user interactive experience with augmented, virtual and mixed reality multimedia content in real world locations.'),
(7529, 236, '_h_sec1_text_content', 'field_59f4f66e924fc'),
