(9199, 242, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(9200, 242, 'h_sec7_road_map_1_open_or_close', '1'),
(9201, 242, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(9202, 242, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(9203, 242, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(9204, 242, 'h_sec7_road_map_2_year', '2016'),
