(9206, 242, 'h_sec7_road_map_2_open_or_close', '1'),
(9207, 242, '_h_sec7_road_map_2_open_or_close', 'field_59f50b06ae597'),
(9208, 242, 'h_sec7_road_map_2_description', 'Launched AR parks the Forum PompeII at Italy  and Ice Road at Russia , we began to develop our own Computer Vision system.'),
(9209, 242, '_h_sec7_road_map_2_description', 'field_59f50aaa13a12'),
(9210, 242, 'h_sec7_road_map_3_year', '2017'),
(9211, 242, '_h_sec7_road_map_3_year', 'field_59f50a9613a11'),
