(9213, 242, '_h_sec7_road_map_3_open_or_close', 'field_59f50b06ae597'),
(9214, 242, 'h_sec7_road_map_3_description', 'We already have launched  8 AR outdoor parks in 6 countries: Russia, France, Latvia, Italy, Estonia and Bulgaria.Started to develop our own augmented reality platform to remotely positioning and  management digital assets .'),
(9215, 242, '_h_sec7_road_map_3_description', 'field_59f50aaa13a12'),
