(13779, 261, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597');
INSERT INTO `znl_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(13780, 261, 'h_sec7_road_map_1_description', 'Запущены AR парки “Крейсер «Аврора»” и «поместье Алтун» в России, AR парк  «Крепость Бастилия» во Франции. Проект в TOP 10 мировых стартапов на «Futur en Seine» (Париж, Франция).'),
(13781, 261, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(13782, 261, 'h_sec7_road_map_2_year', '2016'),
(13783, 261, '_h_sec7_road_map_2_year', 'field_59f50a9613a11'),
