(14327, 262, '_h_sec7_road_map_5_year', 'field_59f50a9613a11'),
(14328, 262, 'h_sec7_road_map_5_open_or_close', '0'),
(14329, 262, '_h_sec7_road_map_5_open_or_close', 'field_59f50b06ae597'),
(14330, 262, 'h_sec7_road_map_5_description', 'Будет запущен маркетплейс, где можно расплачиваться токенами аrcon. Начнется привлечение независимых экспертов к разработке и созданию контента'),
(14331, 262, '_h_sec7_road_map_5_description', 'field_59f50aaa13a12'),
(14332, 262, 'h_sec7_road_map_6_year', '2018 <span>quarter II</span>'),
