(17138, 268, 'h_sec8_adviser_members_0_name', 'Lyubov Simonova'),
(17139, 268, '_h_sec8_adviser_members_0_name', 'field_59f5c35ffa3bd'),
(17140, 268, 'h_sec8_adviser_members_0_description', 'Business lady, business angel, expert in VC, strategy, business development, Internet technologies. More than 20 years experience in building technological Internet projects, 10+years in the venture industry'),
(17141, 268, '_h_sec8_adviser_members_0_description', 'field_59f5c35ffa3be'),
(17142, 268, 'h_sec8_adviser_members_0_social_profiles', '1'),
