(17144, 268, 'h_sec8_adviser_members_1_image', '214'),
(17145, 268, '_h_sec8_adviser_members_1_image', 'field_59f5c35ffa3bc'),
(17146, 268, 'h_sec8_adviser_members_1_name', 'Kairat Kaliev'),
(17147, 268, '_h_sec8_adviser_members_1_name', 'field_59f5c35ffa3bd'),
(17148, 268, 'h_sec8_adviser_members_1_description', 'Founder of Cross Coin, which successfully ran the Starta ICO campaign and raised $ 5 million. Develops FinTech direction in the International Financial Center \"Astana\", specializes in the projects development.'),
(17149, 268, '_h_sec8_adviser_members_1_description', 'field_59f5c35ffa3be'),
(17150, 268, 'h_sec8_adviser_members_1_social_profiles', '1'),
(17151, 268, '_h_sec8_adviser_members_1_social_profiles', 'field_59f5c35ffa3bf'),
(17152, 268, 'h_sec8_adviser_members_2_image', '212'),
(17153, 268, '_h_sec8_adviser_members_2_image', 'field_59f5c35ffa3bc'),
(17154, 268, 'h_sec8_adviser_members_2_name', 'George Popescu'),
(17155, 268, '_h_sec8_adviser_members_2_name', 'field_59f5c35ffa3bd'),
(17156, 268, 'h_sec8_adviser_members_2_description', 'CEO and co -founder of Lampix, an AR technology platform. Founder and Editor in Chief of Lending Times, a media company in the peer-to -peer, market place and online lending space. Chairman of the Board of advisors of Gatecoin, having raised $5.8mil for 1st Blood ICO, $14mil for Lampix ICO, $15mil for AirFox'),
(17157, 268, '_h_sec8_adviser_members_2_description', 'field_59f5c35ffa3be'),
(17158, 268, 'h_sec8_adviser_members_2_social_profiles', '1'),
(17159, 268, '_h_sec8_adviser_members_2_social_profiles', 'field_59f5c35ffa3bf'),
(17160, 268, 'h_sec8_adviser_members_3_image', '213'),
(17161, 268, '_h_sec8_adviser_members_3_image', 'field_59f5c35ffa3bc'),
(17162, 268, 'h_sec8_adviser_members_3_name', 'James Haft'),
(17163, 268, '_h_sec8_adviser_members_3_name', 'field_59f5c35ffa3bd'),
(17164, 268, 'h_sec8_adviser_members_3_description', 'Entrepreneur and Merchant Banker with broad experience in all aspects of forming, managing, advising, fund raising, and biz dev for entrepreneur-powered businesses, including, business strategy and M&A. Advisor or co-founder of global ICOs and Token offerings.'),
(17165, 268, '_h_sec8_adviser_members_3_description', 'field_59f5c35ffa3be'),
(17166, 268, 'h_sec8_adviser_members_3_social_profiles', '1'),
