(17168, 268, 'h_sec8_adviser_members_4_image', '218'),
(17169, 268, '_h_sec8_adviser_members_4_image', 'field_59f5c35ffa3bc'),
(17170, 268, 'h_sec8_adviser_members_4_name', 'Sergey Khitrov'),
(17171, 268, '_h_sec8_adviser_members_4_name', 'field_59f5c35ffa3bd'),
(17172, 268, 'h_sec8_adviser_members_4_description', 'Mentor, blockchain expert. Head of Adwad Group, CPA Adwad.ru, RA JetMedia.pro, organizer of CPA Life, Blockchain Life and a number of other projects'),
(17173, 268, '_h_sec8_adviser_members_4_description', 'field_59f5c35ffa3be'),
(17174, 268, 'h_sec8_adviser_members_4_social_profiles', '1'),
