(17177, 268, '_h_sec8_adviser_members_5_image', 'field_59f5c35ffa3bc'),
(17178, 268, 'h_sec8_adviser_members_5_name', 'Sergei Chmel'),
(17179, 268, '_h_sec8_adviser_members_5_name', 'field_59f5c35ffa3bd'),
(17180, 268, 'h_sec8_adviser_members_5_description', 'Working with startups since 1999 both as an Investment and business development consultant and as an entrepreneur established several companies in different areas. Was involved in gaming, mobile payments, micro lending, nano materials projects as well as valuation and M&A deals. Currently advisor in ICORATING Rating Agency and Managing Partner at ICOSHARK Hedge Fund.'),
(17181, 268, '_h_sec8_adviser_members_5_description', 'field_59f5c35ffa3be'),
