(23460, 283, 'home_sub_form_title', 'Join the community who founded the AR land , limited supply!'),
(23461, 283, '_home_sub_form_title', 'field_59f63f0ca9a3f'),
(23462, 283, 'home_sub_form_description', 'Send us your message indicating how much tokens you are planning to purchase and enter in the draw for the digital land lot in Paris, next to the Eiffel Tower!'),
