(24504, 286, 'h_sec1_youtube_video_embedcode', '<iframe height=\"100%\" width=\"100%\" allowfullscreen=\"\" frameborder=\"0\" title=\"External YouTube\" src=\"//www.youtube.com/embed/s0ERldL5hEE?wmode=transparent&amp;autoplay=0&amp;theme=dark&amp;controls=0&amp;autohide=0&amp;loop=1&amp;showinfo=0&amp;rel=0&amp;playlist=s0ERldL5hEE&amp;enablejsapi=0\"></iframe>'),
(24505, 286, '_h_sec1_youtube_video_embedcode', 'field_59f4f6b2924fe'),
(24506, 286, 'h_sec2_heading', 'AR ECOSYSTEM MAIN FEATURES'),
(24507, 286, '_h_sec2_heading', 'field_59f4fb467be91'),
(24508, 286, 'h_sec2_column_content_0_image', '92'),
(24509, 286, '_h_sec2_column_content_0_image', 'field_59f4fb817be93'),
(24510, 286, 'h_sec2_column_content_0_title', 'SETUP REMOTELY'),
(24511, 286, '_h_sec2_column_content_0_title', 'field_59f4fba67be94'),
(24512, 286, 'h_sec2_column_content_0_description', 'Arcona allows you to place virtual projects anywhere in the world without leaving your home. Choose the most popular and visited places. Create whole worlds on your Digital land'),
(24513, 286, '_h_sec2_column_content_0_description', 'field_59f4fbb87be95'),
(24514, 286, 'h_sec2_column_content_1_image', '94'),
(24515, 286, '_h_sec2_column_content_1_image', 'field_59f4fb817be93'),
(24516, 286, 'h_sec2_column_content_1_title', 'BUILD AND TRADE'),
(24517, 286, '_h_sec2_column_content_1_title', 'field_59f4fba67be94'),
(24518, 286, 'h_sec2_column_content_1_description', 'The world market is open to you in the Arcona ecosystem. Buy, sell, rent out your Digital Land. Make money on creativity, creating and selling the most incredible content.'),
(24519, 286, '_h_sec2_column_content_1_description', 'field_59f4fbb87be95'),
(24520, 286, 'h_sec2_column_content_2_image', '93'),
(24521, 286, '_h_sec2_column_content_2_image', 'field_59f4fb817be93'),
(24522, 286, 'h_sec2_column_content_2_title', 'SAFE PROPERTY'),
(24523, 286, '_h_sec2_column_content_2_title', 'field_59f4fba67be94'),
(24524, 286, 'h_sec2_column_content_2_description', 'Smart contract on blockсhain, guarantees protection of copyright and property rights. The system automates royalty payments to content creators, and rents to digital asset owners'),
(24525, 286, '_h_sec2_column_content_2_description', 'field_59f4fbb87be95'),
(24526, 286, 'h_sec2_column_content', '3'),
(24527, 286, '_h_sec2_column_content', 'field_59f4fb567be92'),
