(25184, 287, 'h_sec7_road_map_4_description', 'November we are holding an ITO with Arcona augmented reality ecosystem powered by team of the Piligrim XXI'),
(25185, 287, '_h_sec7_road_map_4_description', 'field_59f50aaa13a12'),
(25186, 287, 'h_sec7_road_map_5_year', '2018 <span>quarter I</span>'),
