(30095, 312, '_h_sec7_road_map_0_open_or_close', 'field_59f50b06ae597'),
(30096, 312, 'h_sec7_road_map_0_description', 'Launched first outdoor AR park - \"Ludza Castle.\" It increased by 30% the flow of tourists in the region, attracting more than 60,000 tourists/year. Microsoft Seed Fund grant, Accelerations: Intel, Google, Faber Novel. Top 50  russian  startups with  highest rating AAA'),
(30097, 312, '_h_sec7_road_map_0_description', 'field_59f50aaa13a12'),
(30098, 312, 'h_sec7_road_map_1_year', '2015'),
(30099, 312, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(30100, 312, 'h_sec7_road_map_1_open_or_close', '1'),
(30101, 312, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(30102, 312, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(30103, 312, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(30104, 312, 'h_sec7_road_map_2_year', '2016'),
(30105, 312, '_h_sec7_road_map_2_year', 'field_59f50a9613a11'),
(30106, 312, 'h_sec7_road_map_2_open_or_close', '1'),
(30107, 312, '_h_sec7_road_map_2_open_or_close', 'field_59f50b06ae597'),
(30108, 312, 'h_sec7_road_map_2_description', 'Launched AR parks the Forum PompeII at Italy  and Ice Road at Russia , we began to develop our own Computer Vision system.'),
(30109, 312, '_h_sec7_road_map_2_description', 'field_59f50aaa13a12'),
(30110, 312, 'h_sec7_road_map_3_year', '2017'),
(30111, 312, '_h_sec7_road_map_3_year', 'field_59f50a9613a11'),
(30112, 312, 'h_sec7_road_map_3_open_or_close', '1'),
(30113, 312, '_h_sec7_road_map_3_open_or_close', 'field_59f50b06ae597'),
(30114, 312, 'h_sec7_road_map_3_description', 'We already have launched  8 AR outdoor parks in 6 countries: Russia, France, Latvia, Italy, Estonia and Bulgaria.Started to develop our own augmented reality platform to remotely positioning and  management digital assets .'),
(30115, 312, '_h_sec7_road_map_3_description', 'field_59f50aaa13a12'),
