(30120, 312, 'h_sec7_road_map_4_description', 'November we are holding an ITO with Arcona augmented reality ecosystem powered by team of the Piligrim XXI'),
(30121, 312, '_h_sec7_road_map_4_description', 'field_59f50aaa13a12'),
