(30709, 313, '_h_sec7_road_map_7_open_or_close', 'field_59f50b06ae597'),
(30710, 313, 'h_sec7_road_map_7_description', 'Запуск альфа версии  AR GRID, тестирование инструментов дистанционного позиционирования.'),
(30711, 313, '_h_sec7_road_map_7_description', 'field_59f50aaa13a12'),
