(31854, 315, 'h_sec7_heading', 'Arconaの経緯'),
(31855, 315, '_h_sec7_heading', 'field_59f50a7113a0f'),
(31856, 315, 'h_sec7_road_map_0_year', '2014'),
(31857, 315, '_h_sec7_road_map_0_year', 'field_59f50a9613a11'),
(31858, 315, 'h_sec7_road_map_0_open_or_close', '1'),
(31859, 315, '_h_sec7_road_map_0_open_or_close', 'field_59f50b06ae597'),
(31860, 315, 'h_sec7_road_map_0_description', 'Launched first outdoor AR park - \"Ludza Castle.\" It increased by 30% the flow of tourists in the region, attracting more than 60,000 tourists/year. Microsoft Seed Fund grant, Accelerations: Intel, Google, Faber Novel. Top 50  russian  startups with  highest rating AAA'),
(31861, 315, '_h_sec7_road_map_0_description', 'field_59f50aaa13a12'),
(31862, 315, 'h_sec7_road_map_1_year', '2015'),
(31863, 315, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(31864, 315, 'h_sec7_road_map_1_open_or_close', '1'),
(31865, 315, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(31866, 315, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(31867, 315, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(31868, 315, 'h_sec7_road_map_2_year', '2016'),
(31869, 315, '_h_sec7_road_map_2_year', 'field_59f50a9613a11'),
(31870, 315, 'h_sec7_road_map_2_open_or_close', '1'),
(31871, 315, '_h_sec7_road_map_2_open_or_close', 'field_59f50b06ae597'),
(31872, 315, 'h_sec7_road_map_2_description', 'Launched AR parks the Forum PompeII at Italy  and Ice Road at Russia , we began to develop our own Computer Vision system.'),
(31873, 315, '_h_sec7_road_map_2_description', 'field_59f50aaa13a12'),
(31874, 315, 'h_sec7_road_map_3_year', '2017'),
(31875, 315, '_h_sec7_road_map_3_year', 'field_59f50a9613a11'),
(31876, 315, 'h_sec7_road_map_3_open_or_close', '1'),
(31877, 315, '_h_sec7_road_map_3_open_or_close', 'field_59f50b06ae597'),
(31878, 315, 'h_sec7_road_map_3_description', 'We already have launched  8 AR outdoor parks in 6 countries: Russia, France, Latvia, Italy, Estonia and Bulgaria.Started to develop our own augmented reality platform to remotely positioning and  management digital assets .'),
(31879, 315, '_h_sec7_road_map_3_description', 'field_59f50aaa13a12'),
