(31896, 315, 'h_sec7_road_map_6_description', 'Launching the AR Viewer Prototype, motivating users to use the software to earn tokens. Launching Partner’s projects.'),
(31897, 315, '_h_sec7_road_map_6_description', 'field_59f50aaa13a12'),
