(32360, 316, 'h_sec6_top_sponsors', '5'),
(32361, 316, '_h_sec6_top_sponsors', 'field_59f5abab2cd89'),
(32362, 316, 'h_sec6_text_below_sponsors', 'Microsoft Seed Fund grant, accelerations of Intel and Google, Skolkovo Foundation,\r\ntop 20 startups by Booking Booster Programm assisted in our job.'),
(32363, 316, '_h_sec6_text_below_sponsors', 'field_59f5ac0c2cd8c'),
