(34565, 321, '_home_banner_heading', 'field_59f4eb4e6b25d'),
(34566, 321, 'home_banner_sub_heading', 'Buy Tokens - Вecome the Owner of <br>the New Digital Land'),
(34567, 321, '_home_banner_sub_heading', 'field_59f4eb606b25e'),
(34568, 321, 'home_banner_notes_beside_the_countdown', 'Token Sale Start by 27.11.2017\r\nArcona Token Sale: 1 USD = 1 arcona\r\nArcona token will be used for the purchase of all digital goods and services within the ecosystem.'),
(34569, 321, '_home_banner_notes_beside_the_countdown', 'field_59f4eb726b25f'),
(34570, 321, 'home_banner_subscribe_button_title', 'SUBSCRIBE WHITELIST'),
(34571, 321, '_home_banner_subscribe_button_title', 'field_59f4ebd36b260'),
(34572, 321, 'h_sec1_heading', 'AUGMENTED REALITY ECOSYSTEM'),
(34573, 321, '_h_sec1_heading', 'field_59f4f653924fb'),
(34574, 321, 'h_sec1_text_content', 'The Arcona Ecosystem creates a Digital Land - a layer of Augmented Reality uniting the physical and virtual worlds into a single information environment perfectly linked to our real world. It is designed for everyday user interactive experience with augmented, virtual and mixed reality multimedia content in real world locations.'),
(34575, 321, '_h_sec1_text_content', 'field_59f4f66e924fc'),
(34576, 321, 'h_sec1_link_for_the_text_content', 'https://www.arcona.io/'),
(34577, 321, '_h_sec1_link_for_the_text_content', 'field_59f4f6a2924fd'),
(34578, 321, 'h_sec1_youtube_video_embedcode', '<iframe height=\"100%\" width=\"100%\" allowfullscreen=\"\" frameborder=\"0\" title=\"External YouTube\" src=\"//www.youtube.com/embed/s0ERldL5hEE?wmode=transparent&amp;autoplay=0&amp;theme=dark&amp;controls=0&amp;autohide=0&amp;loop=1&amp;showinfo=0&amp;rel=0&amp;playlist=s0ERldL5hEE&amp;enablejsapi=0\"></iframe>'),
(34579, 321, '_h_sec1_youtube_video_embedcode', 'field_59f4f6b2924fe'),
(34580, 321, 'h_sec2_heading', 'AR ECOSYSTEM MAIN FEATURES'),
(34581, 321, '_h_sec2_heading', 'field_59f4fb467be91'),
(34582, 321, 'h_sec2_column_content_0_image', '92'),
(34583, 321, '_h_sec2_column_content_0_image', 'field_59f4fb817be93'),
(34584, 321, 'h_sec2_column_content_0_title', 'SETUP REMOTELY'),
(34585, 321, '_h_sec2_column_content_0_title', 'field_59f4fba67be94'),
(34586, 321, 'h_sec2_column_content_0_description', 'Arcona allows you to place virtual projects anywhere in the world without leaving your home. Choose the most popular and visited places. Create whole worlds on your Digital land'),
(34587, 321, '_h_sec2_column_content_0_description', 'field_59f4fbb87be95'),
(34588, 321, 'h_sec2_column_content_1_image', '94'),
(34589, 321, '_h_sec2_column_content_1_image', 'field_59f4fb817be93'),
(34590, 321, 'h_sec2_column_content_1_title', 'BUILD AND TRADE'),
(34591, 321, '_h_sec2_column_content_1_title', 'field_59f4fba67be94'),
(34592, 321, 'h_sec2_column_content_1_description', 'The world market is open to you in the Arcona ecosystem. Buy, sell, rent out your Digital Land. Make money on creativity, creating and selling the most incredible content.'),
(34593, 321, '_h_sec2_column_content_1_description', 'field_59f4fbb87be95'),
(34594, 321, 'h_sec2_column_content_2_image', '93'),
(34595, 321, '_h_sec2_column_content_2_image', 'field_59f4fb817be93'),
(34596, 321, 'h_sec2_column_content_2_title', 'SAFE PROPERTY'),
(34597, 321, '_h_sec2_column_content_2_title', 'field_59f4fba67be94'),
(34598, 321, 'h_sec2_column_content_2_description', 'Smart contract on blockсhain, guarantees protection of copyright and property rights. The system automates royalty payments to content creators, and rents to digital asset owners'),
(34599, 321, '_h_sec2_column_content_2_description', 'field_59f4fbb87be95'),
(34600, 321, 'h_sec2_column_content', '3'),
(34601, 321, '_h_sec2_column_content', 'field_59f4fb567be92'),
(34602, 321, 'h_sec3_heading', 'YOUR DIGITAL LANDS'),
(34603, 321, '_h_sec3_heading', 'field_59f501a31d0e4'),
(34604, 321, 'h_sec3_image', '101'),
(34605, 321, '_h_sec3_image', 'field_59f501b51d0e5'),
(34606, 321, 'h_sec3_text_content', 'Digital Land is the main asset of the Arcona ecosystem, built on the principles of blockchain. You can buy your own lot of Digital Land in exchange for an ERC20 standard token -- Arcona. Each lot of the Digital Land is associated with a specific location in the physical world. You can use your plot of Digital Land to create any augmented reality online project that you can imagine, including, but not limited to:\r\n<ul>\r\n<li>creating games</li>\r\n<li>opening virtual stores</li>\r\n<li>organizing events, shows and presentations. </li>\r\n</ul>\r\n\r\nWe are launching an ITO in order to start the process of generating Digital Land as early as 2019. The first digitized territories will appear in the 10 largest cities in the world:\r\n<ul class=\"half\">\r\n<li>New York</li>\r\n<li>London</li>\r\n<li>Paris</li>\r\n<li>Tokyo</li>\r\n<li>Beijing</li>\r\n</ul>\r\n<ul class=\"half\">\r\n<li>Rome</li>\r\n<li>Mexico</li>\r\n<li>St. Petersburg</li>\r\n<li>Istanbul</li>\r\n<li>Barcelona</li>\r\n</ul>\r\n'),
(34607, 321, '_h_sec3_text_content', 'field_59f501c91d0e6'),
(34608, 321, 'h_sec4_heading', 'ARCONA ECOSYSTEM'),
(34609, 321, '_h_sec4_heading', 'field_59f503ac089e2'),
(34610, 321, 'h_sec4_image', '318'),
(34611, 321, '_h_sec4_image', 'field_59f503c4089e3'),
(34612, 321, 'h_sec5_heading', 'ARCONA TOKEN SALE'),
(34613, 321, '_h_sec5_heading', 'field_59f5069450063'),
(34614, 321, 'h_sec5_text_content', '<div class=\"coins\">\r\n<img src=\"/wp-content/uploads/2017/11/coin1.png\" alt=\"\">\r\n<img src=\"/wp-content/uploads/2017/11/coin2.png\" alt=\"\">\r\n</div>\r\n<p class=\"type1\">Arcona will be introduced in the first quarter of 2018</p>\r\n<p class=\"type2\">The arcona token help you to purchase digital lands and other digital assets.</p>\r\n<p class=\"type2\">You can get arcona as a reward for performing tasks set by the Arcona system.</p>\r\n<p class=\"type3\">Total emission — 100 000 000 arconas</p>\r\n<p class=\"type4\">DISTRIBUTION OF TOKENS</p>'),
(34615, 321, '_h_sec5_text_content', 'field_59f506dd50064'),
(34616, 321, 'h_sec5_image', '115'),
(34617, 321, '_h_sec5_image', 'field_59f5074750065'),
