(35309, 322, '_h_sec7_road_map_0_open_or_close', 'field_59f50b06ae597'),
(35310, 322, 'h_sec7_road_map_0_description', 'Launched first outdoor AR park - \"Ludza Castle.\" It increased by 30% the flow of tourists in the region, attracting more than 60,000 tourists/year. Microsoft Seed Fund grant, Accelerations: Intel, Google, Faber Novel. Top 50  russian  startups with  highest rating AAA'),
(35311, 322, '_h_sec7_road_map_0_description', 'field_59f50aaa13a12'),
(35312, 322, 'h_sec7_road_map_1_year', '2015'),
(35313, 322, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(35314, 322, 'h_sec7_road_map_1_open_or_close', '1'),
(35315, 322, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(35316, 322, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(35317, 322, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(35318, 322, 'h_sec7_road_map_2_year', '2016'),
(35319, 322, '_h_sec7_road_map_2_year', 'field_59f50a9613a11'),
(35320, 322, 'h_sec7_road_map_2_open_or_close', '1'),
(35321, 322, '_h_sec7_road_map_2_open_or_close', 'field_59f50b06ae597'),
(35322, 322, 'h_sec7_road_map_2_description', 'Launched AR parks the Forum PompeII at Italy  and Ice Road at Russia , we began to develop our own Computer Vision system.'),
(35323, 322, '_h_sec7_road_map_2_description', 'field_59f50aaa13a12'),
(35324, 322, 'h_sec7_road_map_3_year', '2017'),
(35325, 322, '_h_sec7_road_map_3_year', 'field_59f50a9613a11'),
(35326, 322, 'h_sec7_road_map_3_open_or_close', '1'),
(35327, 322, '_h_sec7_road_map_3_open_or_close', 'field_59f50b06ae597'),
(35328, 322, 'h_sec7_road_map_3_description', 'We already have launched  8 AR outdoor parks in 6 countries: Russia, France, Latvia, Italy, Estonia and Bulgaria.Started to develop our own augmented reality platform to remotely positioning and  management digital assets .'),
(35329, 322, '_h_sec7_road_map_3_description', 'field_59f50aaa13a12'),
