(35699, 325, '_home_banner_top_buttons', 'field_59f4ea9061b70'),
(35700, 325, 'home_banner_heading', 'Augmented Reality World Discovered'),
(35701, 325, '_home_banner_heading', 'field_59f4eb4e6b25d'),
(35702, 325, 'home_banner_sub_heading', 'Buy Tokens - Вecome the Owner of <br>the New Digital Land'),
(35703, 325, '_home_banner_sub_heading', 'field_59f4eb606b25e'),
(35704, 325, 'home_banner_notes_beside_the_countdown', 'Token Sale Start by 27.11.2017\r\nArcona Token Sale: 1 USD = 1 arcona\r\nArcona token will be used for the purchase of all digital goods and services within the ecosystem.'),
(35705, 325, '_home_banner_notes_beside_the_countdown', 'field_59f4eb726b25f'),
(35706, 325, 'home_banner_subscribe_button_title', 'SUBSCRIBE WHITELIST'),
(35707, 325, '_home_banner_subscribe_button_title', 'field_59f4ebd36b260'),
(35708, 325, 'h_sec1_heading', 'AUGMENTED REALITY ECOSYSTEM'),
(35709, 325, '_h_sec1_heading', 'field_59f4f653924fb'),
(35710, 325, 'h_sec1_text_content', 'The Arcona Ecosystem creates a Digital Land - a layer of Augmented Reality uniting the physical and virtual worlds into a single information environment perfectly linked to our real world. It is designed for everyday user interactive experience with augmented, virtual and mixed reality multimedia content in real world locations.'),
(35711, 325, '_h_sec1_text_content', 'field_59f4f66e924fc'),
(35712, 325, 'h_sec1_link_for_the_text_content', 'https://www.arcona.io/'),
(35713, 325, '_h_sec1_link_for_the_text_content', 'field_59f4f6a2924fd'),
(35714, 325, 'h_sec1_youtube_video_embedcode', '<iframe height=\"100%\" width=\"100%\" allowfullscreen=\"\" frameborder=\"0\" title=\"External YouTube\" src=\"//www.youtube.com/embed/s0ERldL5hEE?wmode=transparent&amp;autoplay=0&amp;theme=dark&amp;controls=0&amp;autohide=0&amp;loop=1&amp;showinfo=0&amp;rel=0&amp;playlist=s0ERldL5hEE&amp;enablejsapi=0\"></iframe>'),
(35715, 325, '_h_sec1_youtube_video_embedcode', 'field_59f4f6b2924fe'),
(35716, 325, 'h_sec2_heading', 'AR ECOSYSTEM MAIN FEATURES'),
(35717, 325, '_h_sec2_heading', 'field_59f4fb467be91'),
(35718, 325, 'h_sec2_column_content_0_image', '92'),
(35719, 325, '_h_sec2_column_content_0_image', 'field_59f4fb817be93'),
(35720, 325, 'h_sec2_column_content_0_title', 'SETUP REMOTELY'),
(35721, 325, '_h_sec2_column_content_0_title', 'field_59f4fba67be94'),
(35722, 325, 'h_sec2_column_content_0_description', 'Arcona allows you to place virtual projects anywhere in the world without leaving your home. Choose the most popular and visited places. Create whole worlds on your Digital land'),
(35723, 325, '_h_sec2_column_content_0_description', 'field_59f4fbb87be95'),
(35724, 325, 'h_sec2_column_content_1_image', '94'),
(35725, 325, '_h_sec2_column_content_1_image', 'field_59f4fb817be93'),
(35726, 325, 'h_sec2_column_content_1_title', 'BUILD AND TRADE'),
(35727, 325, '_h_sec2_column_content_1_title', 'field_59f4fba67be94'),
(35728, 325, 'h_sec2_column_content_1_description', 'The world market is open to you in the Arcona ecosystem. Buy, sell, rent out your Digital Land. Make money on creativity, creating and selling the most incredible content.'),
(35729, 325, '_h_sec2_column_content_1_description', 'field_59f4fbb87be95'),
(35730, 325, 'h_sec2_column_content_2_image', '93'),
(35731, 325, '_h_sec2_column_content_2_image', 'field_59f4fb817be93'),
(35732, 325, 'h_sec2_column_content_2_title', 'SAFE PROPERTY'),
(35733, 325, '_h_sec2_column_content_2_title', 'field_59f4fba67be94'),
(35734, 325, 'h_sec2_column_content_2_description', 'Smart contract on blockсhain, guarantees protection of copyright and property rights. The system automates royalty payments to content creators, and rents to digital asset owners'),
(35735, 325, '_h_sec2_column_content_2_description', 'field_59f4fbb87be95'),
(35736, 325, 'h_sec2_column_content', '3'),
(35737, 325, '_h_sec2_column_content', 'field_59f4fb567be92'),
(35738, 325, 'h_sec3_heading', 'YOUR DIGITAL LANDS'),
(35739, 325, '_h_sec3_heading', 'field_59f501a31d0e4'),
(35740, 325, 'h_sec3_image', '101'),
(35741, 325, '_h_sec3_image', 'field_59f501b51d0e5'),
(35742, 325, 'h_sec3_text_content', 'Digital Land is the main asset of the Arcona ecosystem, built on the principles of blockchain. You can buy your own lot of Digital Land in exchange for an ERC20 standard token -- Arcona. Each lot of the Digital Land is associated with a specific location in the physical world. You can use your plot of Digital Land to create any augmented reality online project that you can imagine, including, but not limited to:\r\n<ul>\r\n<li>creating games</li>\r\n<li>opening virtual stores</li>\r\n<li>organizing events, shows and presentations. </li>\r\n</ul>\r\n\r\nWe are launching an ITO in order to start the process of generating Digital Land as early as 2019. The first digitized territories will appear in the 10 largest cities in the world:\r\n<ul class=\"half\">\r\n<li>New York</li>\r\n<li>London</li>\r\n<li>Paris</li>\r\n<li>Tokyo</li>\r\n<li>Beijing</li>\r\n</ul>\r\n<ul class=\"half\">\r\n<li>Rome</li>\r\n<li>Mexico</li>\r\n<li>St. Petersburg</li>\r\n<li>Istanbul</li>\r\n<li>Barcelona</li>\r\n</ul>\r\n'),
(35743, 325, '_h_sec3_text_content', 'field_59f501c91d0e6'),
(35744, 325, 'h_sec4_heading', 'ARCONA ECOSYSTEM'),
(35745, 325, '_h_sec4_heading', 'field_59f503ac089e2'),
(35746, 325, 'h_sec4_image', '318'),
(35747, 325, '_h_sec4_image', 'field_59f503c4089e3'),
(35748, 325, 'h_sec5_heading', 'ARCONA TOKEN SALE'),
(35749, 325, '_h_sec5_heading', 'field_59f5069450063'),
(35750, 325, 'h_sec5_text_content', '<div class=\"coins\">\r\n<img src=\"/wp-content/uploads/2017/11/coin1.png\" alt=\"\">\r\n<img src=\"/wp-content/uploads/2017/11/coin2.png\" alt=\"\">\r\n</div>\r\n<p class=\"type1\">Arcona will be introduced in the first quarter of 2018</p>\r\n<p class=\"type2\">The arcona token help you to purchase digital lands and other digital assets.</p>\r\n<p class=\"type2\">You can get arcona as a reward for performing tasks set by the Arcona system.</p>\r\n<p class=\"type3\">Total emission — 100 000 000 arconas</p>\r\n<p class=\"type4\">DISTRIBUTION OF TOKENS</p>'),
(35751, 325, '_h_sec5_text_content', 'field_59f506dd50064'),
(35752, 325, 'h_sec5_image', '115'),
(35753, 325, '_h_sec5_image', 'field_59f5074750065'),
(35754, 325, 'h_sec5_subscribe_button_text', 'Subscribe Now'),
(35755, 325, '_h_sec5_subscribe_button_text', 'field_59fb496893fd7'),
(35756, 325, 'h_sec5_section_id_with_hash_to_scroll', '#sectionElaven'),
(35757, 325, '_h_sec5_section_id_with_hash_to_scroll', 'field_59fb499393fd8'),
(35758, 325, 'h_sec6_heading', 'WHO IF NOT US?'),
(35759, 325, '_h_sec6_heading', 'field_59f5ab312cd86'),
(35760, 325, 'h_sec6_image', '158'),
(35761, 325, '_h_sec6_image', 'field_59f5ab5b2cd87'),
(35762, 325, 'h_sec6_top_text_content', 'The Arcona platform is being developed by the professional team of <a href=\"//www.piligrimxxi.com/presskit\" target=\"_blank\">PiligrimXXI</a>. Since 2015, PiligrimXXI has been actively investing its own funds to research the field of distributed GIS system, Augmented Reality technologies, 3D simulations, Computer vision and Artificial Intelligence and is the first Russian IT start-up operating in the international augmented reality market in the travel industry. \r\n\r\nPiligrimXXI has given tourists the opportunity to combine real travel and time travel. We have launched the world’s first augmented reality parks in a total of 8 parks in 6 countries. Using a smartphone and AR headset, travelers can see with their own eyes the architectural wonders of the past and witness historical events in real time. \r\n\r\n<h3 class=\"headingtype2 text-center\">We Were Assisted by the Following Great Companies</h3>'),
(35763, 325, '_h_sec6_top_text_content', 'field_59f5ab7d2cd88'),
(35764, 325, 'h_sec6_top_sponsors_0_logo', '162'),
