(35885, 325, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(35886, 325, 'h_sec7_road_map_1_open_or_close', '1'),
(35887, 325, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(35888, 325, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(35889, 325, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(35890, 325, 'h_sec7_road_map_2_year', '2016'),
