(36474, 342, '_h_sec6_top_sponsors_3_logo', 'field_59f5abdf2cd8a'),
(36475, 342, 'h_sec6_top_sponsors_4_logo', '159'),
(36476, 342, '_h_sec6_top_sponsors_4_logo', 'field_59f5abdf2cd8a'),
(36477, 342, 'h_sec6_top_sponsors', '5'),
(36478, 342, '_h_sec6_top_sponsors', 'field_59f5abab2cd89'),
(36479, 342, 'h_sec6_text_below_sponsors', 'Microsoft Seed Fund grant, accelerations of Intel and Google, Skolkovo Foundation,\r\ntop 20 startups by Booking Booster Programm assisted in our job.'),
