(36590, 342, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(36591, 342, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(36592, 342, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(36593, 342, 'h_sec7_road_map_2_year', '2016'),
