(38545, 346, '_h_sec8_adviser_members_3_name', 'field_59f5c35ffa3bd'),
(38546, 346, 'h_sec8_adviser_members_3_description', 'Entrepreneur and Merchant Banker with broad experience in all aspects of forming, managing, advising, fund raising, and biz dev for entrepreneur-powered businesses, including, business strategy and M&A. Advisor or co-founder of global ICOs and Token offerings.'),
(38547, 346, '_h_sec8_adviser_members_3_description', 'field_59f5c35ffa3be'),
