(39337, 356, 'home_banner_top_buttons_0_link', '//q-r.to/arconalp'),
(39338, 356, '_home_banner_top_buttons_0_link', 'field_59f4eae061b72'),
(39339, 356, 'home_banner_top_buttons_1_title', 'WHITE PAPER'),
(39340, 356, '_home_banner_top_buttons_1_title', 'field_59f4eace61b71'),
(39341, 356, 'home_banner_top_buttons_1_link', 'https://docs.google.com/document/d/1JbrIS5c-IDLbeiuOrycv2Fa91NG2xUkMabOWoevToRw/edit'),
(39342, 356, '_home_banner_top_buttons_1_link', 'field_59f4eae061b72'),
(39343, 356, 'home_banner_top_buttons', '2'),
(39344, 356, '_home_banner_top_buttons', 'field_59f4ea9061b70'),
(39345, 356, 'home_banner_heading', 'A Blockchain Powered Ecosystem merging together<br>  real and virtual worlds worldwide creating augmented reality layer  <br>The Digital Land'),
(39346, 356, '_home_banner_heading', 'field_59f4eb4e6b25d'),
(39347, 356, 'home_banner_sub_heading', 'Buy Tokens Arcona - Вecome the Owner<br>of the New Digital Land</small>'),
(39348, 356, '_home_banner_sub_heading', 'field_59f4eb606b25e'),
(39349, 356, 'home_banner_notes_beside_the_countdown', 'Token Sale Start by 27.11.2017\r\nArcona Token Sale: 1 USD = 1 arcona\r\nArcona token will be used for the purchase of all digital goods and services within the ecosystem.'),
(39350, 356, '_home_banner_notes_beside_the_countdown', 'field_59f4eb726b25f'),
(39351, 356, 'home_banner_subscribe_button_title', 'Buy arcona tokens NOW1'),
(39352, 356, '_home_banner_subscribe_button_title', 'field_59f4ebd36b260'),
(39353, 356, 'h_sec1_heading', 'AUGMENTED REALITY ECOSYSTEM'),
(39354, 356, '_h_sec1_heading', 'field_59f4f653924fb'),
(39355, 356, 'h_sec1_text_content', 'The Arcona Ecosystem creates a Digital Land - a layer of Augmented Reality uniting the physical and virtual worlds into a single information environment perfectly linked to our real world. It is designed for everyday user interactive experience with augmented, virtual and mixed reality multimedia content in real world locations.'),
(39356, 356, '_h_sec1_text_content', 'field_59f4f66e924fc'),
(39357, 356, 'h_sec1_link_for_the_text_content', 'https://www.arcona.io/'),
(39358, 356, '_h_sec1_link_for_the_text_content', 'field_59f4f6a2924fd'),
(39359, 356, 'h_sec1_youtube_video_embedcode', '<iframe height=\"100%\" width=\"100%\" allowfullscreen=\"\" frameborder=\"0\" title=\"External YouTube\" src=\"//www.youtube.com/embed/s0ERldL5hEE?wmode=transparent&amp;autoplay=0&amp;theme=dark&amp;controls=0&amp;autohide=0&amp;loop=1&amp;showinfo=0&amp;rel=0&amp;playlist=s0ERldL5hEE&amp;enablejsapi=0\"></iframe>'),
(39360, 356, '_h_sec1_youtube_video_embedcode', 'field_59f4f6b2924fe'),
(39361, 356, 'h_sec2_heading', 'AR ECOSYSTEM MAIN FEATURES'),
(39362, 356, '_h_sec2_heading', 'field_59f4fb467be91'),
(39363, 356, 'h_sec2_column_content_0_image', '92'),
(39364, 356, '_h_sec2_column_content_0_image', 'field_59f4fb817be93'),
(39365, 356, 'h_sec2_column_content_0_title', 'SETUP REMOTELY'),
(39366, 356, '_h_sec2_column_content_0_title', 'field_59f4fba67be94'),
(39367, 356, 'h_sec2_column_content_0_description', 'Arcona allows you to place virtual projects anywhere in the world without leaving your home. Choose the most popular and visited places. Create whole worlds on your Digital land'),
(39368, 356, '_h_sec2_column_content_0_description', 'field_59f4fbb87be95'),
(39369, 356, 'h_sec2_column_content_1_image', '94'),
(39370, 356, '_h_sec2_column_content_1_image', 'field_59f4fb817be93'),
(39371, 356, 'h_sec2_column_content_1_title', 'BUILD AND TRADE'),
(39372, 356, '_h_sec2_column_content_1_title', 'field_59f4fba67be94'),
(39373, 356, 'h_sec2_column_content_1_description', 'The world market is open to you in the Arcona ecosystem. Buy, sell, rent out your Digital Land. Make money on creativity, creating and selling the most incredible content.'),
(39374, 356, '_h_sec2_column_content_1_description', 'field_59f4fbb87be95'),
(39375, 356, 'h_sec2_column_content_2_image', '93'),
(39376, 356, '_h_sec2_column_content_2_image', 'field_59f4fb817be93'),
(39377, 356, 'h_sec2_column_content_2_title', 'SAFE PROPERTY'),
(39378, 356, '_h_sec2_column_content_2_title', 'field_59f4fba67be94'),
(39379, 356, 'h_sec2_column_content_2_description', 'Smart contract on blockсhain, guarantees protection of copyright and property rights. The system automates royalty payments to content creators, and rents to digital asset owners'),
(39380, 356, '_h_sec2_column_content_2_description', 'field_59f4fbb87be95'),
(39381, 356, 'h_sec2_column_content', '3'),
(39382, 356, '_h_sec2_column_content', 'field_59f4fb567be92'),
(39383, 356, 'h_sec3_heading', 'YOUR DIGITAL LANDS'),
(39384, 356, '_h_sec3_heading', 'field_59f501a31d0e4'),
(39385, 356, 'h_sec3_image', '101'),
(39386, 356, '_h_sec3_image', 'field_59f501b51d0e5'),
(39387, 356, 'h_sec3_text_content', 'Digital Land is the main asset of the Arcona ecosystem, built on the principles of blockchain. You can buy your own lot of Digital Land in exchange for an ERC20 standard token -- Arcona. Each lot of the Digital Land is associated with a specific location in the physical world. You can use your plot of Digital Land to create any augmented reality online project that you can imagine, including, but not limited to:\r\n<ul>\r\n<li>creating games</li>\r\n<li>opening virtual stores</li>\r\n<li>organizing events, shows and presentations. </li>\r\n</ul>\r\n\r\nWe are launching an ITO in order to start the process of generating Digital Land as early as 2019. The first digitized territories will appear in the 10 largest cities in the world:\r\n<ul class=\"half\">\r\n<li>New York</li>\r\n<li>London</li>\r\n<li>Paris</li>\r\n<li>Tokyo</li>\r\n<li>Beijing</li>\r\n</ul>\r\n<ul class=\"half\">\r\n<li>Rome</li>\r\n<li>Mexico</li>\r\n<li>St. Petersburg</li>\r\n<li>Istanbul</li>\r\n<li>Barcelona</li>\r\n</ul>\r\n'),
(39388, 356, '_h_sec3_text_content', 'field_59f501c91d0e6'),
(39389, 356, 'h_sec4_heading', 'ARCONA ECOSYSTEM'),
(39390, 356, '_h_sec4_heading', 'field_59f503ac089e2'),
(39391, 356, 'h_sec4_image', '318'),
(39392, 356, '_h_sec4_image', 'field_59f503c4089e3'),
(39393, 356, 'h_sec5_heading', 'ARCONA TOKEN SALE'),
(39394, 356, '_h_sec5_heading', 'field_59f5069450063'),
(39395, 356, 'h_sec5_text_content', '<div class=\"coins\">\r\n<img src=\"/wp-content/uploads/2017/11/coin1.png\" alt=\"\">\r\n<img src=\"/wp-content/uploads/2017/11/coin2.png\" alt=\"\">\r\n</div>\r\n<p class=\"type1\">Arcona will be introduced in the first quarter of 2018</p>\r\n<p class=\"type2\">The arcona token help you to purchase digital lands and other digital assets.</p>\r\n<p class=\"type2\">You can get arcona as a reward for performing tasks set by the Arcona system.</p>\r\n<p class=\"type3\">Total emission — 100 000 000 arconas</p>\r\n<p class=\"type4\">DISTRIBUTION OF TOKENS</p>'),
(39396, 356, '_h_sec5_text_content', 'field_59f506dd50064'),
(39397, 356, 'h_sec5_image', '115'),
(39398, 356, '_h_sec5_image', 'field_59f5074750065'),
(39399, 356, 'h_sec5_subscribe_button_text', 'Subscribe Now'),
(39400, 356, '_h_sec5_subscribe_button_text', 'field_59fb496893fd7'),
(39401, 356, 'h_sec5_section_id_with_hash_to_scroll', '#sectionElaven'),
(39402, 356, '_h_sec5_section_id_with_hash_to_scroll', 'field_59fb499393fd8'),
(39403, 356, 'h_sec6_heading', 'WHO IF NOT US?'),
(39404, 356, '_h_sec6_heading', 'field_59f5ab312cd86'),
(39405, 356, 'h_sec6_image', '158'),
(39406, 356, '_h_sec6_image', 'field_59f5ab5b2cd87'),
(39407, 356, 'h_sec6_top_text_content', 'The Arcona platform is being developed by the professional team of <a href=\"//www.piligrimxxi.com/presskit\" target=\"_blank\">PiligrimXXI</a>. Since 2015, PiligrimXXI has been actively investing its own funds to research the field of distributed GIS system, Augmented Reality technologies, 3D simulations, Computer vision and Artificial Intelligence and is the first Russian IT start-up operating in the international augmented reality market in the travel industry. \r\n\r\nPiligrimXXI has given tourists the opportunity to combine real travel and time travel. We have launched the world’s first augmented reality parks in a total of 8 parks in 6 countries. Using a smartphone and AR headset, travelers can see with their own eyes the architectural wonders of the past and witness historical events in real time. \r\n\r\n<h3 class=\"headingtype2 text-center\">We Were Assisted by the Following Great Companies</h3>'),
(39408, 356, '_h_sec6_top_text_content', 'field_59f5ab7d2cd88'),
(39409, 356, 'h_sec6_top_sponsors_0_logo', '162'),
(39410, 356, '_h_sec6_top_sponsors_0_logo', 'field_59f5abdf2cd8a'),
