(39412, 356, '_h_sec6_top_sponsors_1_logo', 'field_59f5abdf2cd8a'),
(39413, 356, 'h_sec6_top_sponsors_2_logo', '160'),
(39414, 356, '_h_sec6_top_sponsors_2_logo', 'field_59f5abdf2cd8a'),
(39415, 356, 'h_sec6_top_sponsors_3_logo', '163'),
