(41821, 360, '_h_sec7_road_map_0_open_or_close', 'field_59f50b06ae597'),
(41822, 360, 'h_sec7_road_map_0_description', 'Launched first outdoor AR park - \"Ludza Castle.\" It increased by 30% the flow of tourists in the region, attracting more than 60,000 tourists/year. Microsoft Seed Fund grant, Accelerations: Intel, Google, Faber Novel. Top 50  russian  startups with  highest rating AAA'),
(41823, 360, '_h_sec7_road_map_0_description', 'field_59f50aaa13a12'),
(41824, 360, 'h_sec7_road_map_1_year', '2015'),
(41825, 360, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(41826, 360, 'h_sec7_road_map_1_open_or_close', '1'),
(41827, 360, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(41828, 360, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(41829, 360, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(41830, 360, 'h_sec7_road_map_2_year', '2016'),
