(44310, 368, '_h_sec8_adviser_members_4_name', 'field_59f5c35ffa3bd'),
(44311, 368, 'h_sec8_adviser_members_4_description', 'Mentor, blockchain expert. Head of Adwad Group, CPA Adwad.ru, RA JetMedia.pro, organizer of CPA Life, Blockchain Life and a number of other projects'),
