(44443, 369, 'home_banner_image', '56'),
(44444, 369, '_home_banner_image', 'field_59f4ea7961b6f'),
(44445, 369, 'home_banner_top_buttons_0_title', 'LIGHT PAPER'),
(44446, 369, '_home_banner_top_buttons_0_title', 'field_59f4eace61b71'),
