(45751, 376, 'h_sec7_road_map_2_description', 'Launched AR parks the Forum PompeII at Italy  and Ice Road at Russia , we began to develop our own Computer Vision system.'),
(45752, 376, '_h_sec7_road_map_2_description', 'field_59f50aaa13a12'),
(45753, 376, 'h_sec7_road_map_3_year', '2017'),
(45754, 376, '_h_sec7_road_map_3_year', 'field_59f50a9613a11'),
