INSERT INTO `znl_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(46308, 377, '_h_sec7_road_map_0_year', 'field_59f50a9613a11'),
(46309, 377, 'h_sec7_road_map_0_open_or_close', '1'),
(46310, 377, '_h_sec7_road_map_0_open_or_close', 'field_59f50b06ae597'),
(46311, 377, 'h_sec7_road_map_0_description', 'Launched first outdoor AR park - \"Ludza Castle.\" It increased by 30% the flow of tourists in the region, attracting more than 60,000 tourists/year. Microsoft Seed Fund grant, Accelerations: Intel, Google, Faber Novel. Top 50  russian  startups with  highest rating AAA'),
(46312, 377, '_h_sec7_road_map_0_description', 'field_59f50aaa13a12'),
(46313, 377, 'h_sec7_road_map_1_year', '2015'),
(46314, 377, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(46315, 377, 'h_sec7_road_map_1_open_or_close', '1'),
(46316, 377, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(46317, 377, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(46318, 377, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(46319, 377, 'h_sec7_road_map_2_year', '2016'),
(46320, 377, '_h_sec7_road_map_2_year', 'field_59f50a9613a11'),
(46321, 377, 'h_sec7_road_map_2_open_or_close', '1'),
(46322, 377, '_h_sec7_road_map_2_open_or_close', 'field_59f50b06ae597'),
(46323, 377, 'h_sec7_road_map_2_description', 'Launched AR parks the Forum PompeII at Italy  and Ice Road at Russia , we began to develop our own Computer Vision system.'),
(46324, 377, '_h_sec7_road_map_2_description', 'field_59f50aaa13a12'),
(46325, 377, 'h_sec7_road_map_3_year', '2017'),
(46326, 377, '_h_sec7_road_map_3_year', 'field_59f50a9613a11'),
(46327, 377, 'h_sec7_road_map_3_open_or_close', '1'),
(46328, 377, '_h_sec7_road_map_3_open_or_close', 'field_59f50b06ae597'),
(46329, 377, 'h_sec7_road_map_3_description', 'We already have launched  8 AR outdoor parks in 6 countries: Russia, France, Latvia, Italy, Estonia and Bulgaria.Started to develop our own augmented reality platform to remotely positioning and  management digital assets .'),
(46330, 377, '_h_sec7_road_map_3_description', 'field_59f50aaa13a12'),
