INSERT INTO `znl_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(47463, 379, 'h_sec7_road_map_0_description', 'Launched first outdoor AR park - \"Ludza Castle.\" It increased by 30% the flow of tourists in the region, attracting more than 60,000 tourists/year. Microsoft Seed Fund grant, Accelerations: Intel, Google, Faber Novel. Top 50  russian  startups with  highest rating AAA'),
(47464, 379, '_h_sec7_road_map_0_description', 'field_59f50aaa13a12'),
