(47475, 379, 'h_sec7_road_map_2_description', 'Launched AR parks the Forum PompeII at Italy  and Ice Road at Russia , we began to develop our own Computer Vision system.'),
(47476, 379, '_h_sec7_road_map_2_description', 'field_59f50aaa13a12'),
(47477, 379, 'h_sec7_road_map_3_year', '2017'),
