(48994, 384, '_h_sec1_link_for_the_text_content', 'field_59f4f6a2924fd'),
(48993, 384, 'h_sec1_link_for_the_text_content', 'https://www.arcona.io/'),
(48992, 384, '_h_sec1_text_content', 'field_59f4f66e924fc'),
(48991, 384, 'h_sec1_text_content', 'The Arcona Ecosystem creates a Digital Land - a layer of Augmented Reality uniting the physical and virtual worlds into a single information environment perfectly linked to our real world. It is designed for everyday user interactive experience with augmented, virtual and mixed reality multimedia content in real world locations.'),
(48990, 384, '_h_sec1_heading', 'field_59f4f653924fb'),
(48989, 384, 'h_sec1_heading', 'AUGMENTED REALITY ECOSYSTEM'),
