(50306, 386, '_h_sec7_road_map_0_open_or_close', 'field_59f50b06ae597'),
(50307, 386, 'h_sec7_road_map_0_description', 'Launched first outdoor AR park - \"Ludza Castle.\" It increased by 30% the flow of tourists in the region, attracting more than 60,000 tourists/year. Microsoft Seed Fund grant, Accelerations: Intel, Google, Faber Novel. Top 50  russian  startups with  highest rating AAA'),
(50308, 386, '_h_sec7_road_map_0_description', 'field_59f50aaa13a12'),
(50309, 386, 'h_sec7_road_map_1_year', '2015'),
(50310, 386, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(50311, 386, 'h_sec7_road_map_1_open_or_close', '1'),
(50312, 386, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(50313, 386, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(50314, 386, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(50315, 386, 'h_sec7_road_map_2_year', '2016'),
