(50855, 387, 'h_sec7_road_map_0_description', 'Launched first outdoor AR park - \"Ludza Castle.\" It increased by 30% the flow of tourists in the region, attracting more than 60,000 tourists/year. Microsoft Seed Fund grant, Accelerations: Intel, Google, Faber Novel. Top 50  russian  startups with  highest rating AAA'),
(50856, 387, '_h_sec7_road_map_0_description', 'field_59f50aaa13a12'),
(50857, 387, 'h_sec7_road_map_1_year', '2015'),
(50858, 387, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(50859, 387, 'h_sec7_road_map_1_open_or_close', '1'),
(50860, 387, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(50861, 387, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(50862, 387, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(50863, 387, 'h_sec7_road_map_2_year', '2016'),
