(50865, 387, 'h_sec7_road_map_2_open_or_close', '1'),
(50866, 387, '_h_sec7_road_map_2_open_or_close', 'field_59f50b06ae597'),
(50867, 387, 'h_sec7_road_map_2_description', 'Launched AR parks the Forum PompeII at Italy  and Ice Road at Russia , we began to develop our own Computer Vision system.'),
(50868, 387, '_h_sec7_road_map_2_description', 'field_59f50aaa13a12'),
(50869, 387, 'h_sec7_road_map_3_year', '2017'),
(50870, 387, '_h_sec7_road_map_3_year', 'field_59f50a9613a11'),
(50871, 387, 'h_sec7_road_map_3_open_or_close', '1'),
(50872, 387, '_h_sec7_road_map_3_open_or_close', 'field_59f50b06ae597'),
(50873, 387, 'h_sec7_road_map_3_description', 'We already have launched  8 AR outdoor parks in 6 countries: Russia, France, Latvia, Italy, Estonia and Bulgaria.Started to develop our own augmented reality platform to remotely positioning and  management digital assets .'),
(50874, 387, '_h_sec7_road_map_3_description', 'field_59f50aaa13a12'),
