(51236, 388, '_h_sec1_youtube_video_embedcode', 'field_59f4f6b2924fe'),
(51237, 388, 'h_sec2_heading', 'ПРЕИМУЩЕСТВА  AR ЭКОСИСТЕМЫ'),
