(51969, 389, 'h_sec7_heading', 'ДОРОЖНАЯ КАРТА'),
(51970, 389, '_h_sec7_heading', 'field_59f50a7113a0f'),
(51971, 389, 'h_sec7_road_map_0_year', '2014'),
(51972, 389, '_h_sec7_road_map_0_year', 'field_59f50a9613a11'),
(51973, 389, 'h_sec7_road_map_0_open_or_close', '1'),
(51974, 389, '_h_sec7_road_map_0_open_or_close', 'field_59f50b06ae597'),
(51975, 389, 'h_sec7_road_map_0_description', 'Запущен первый AR  парк под открытым небом «Лудзенский  замок». За первый год  он привлек более 60 000 пользователей и увеличил турпоток на 30%. Получен грант Microsoft Seed Fund. Пройдена акселерация Intel, Google и Faber Novel. Проект в Топ-50 российских стартапов с наивысшим инвестрейтингом AAA'),
(51976, 389, '_h_sec7_road_map_0_description', 'field_59f50aaa13a12'),
(51977, 389, 'h_sec7_road_map_1_year', '2015'),
(51978, 389, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(51979, 389, 'h_sec7_road_map_1_open_or_close', '1'),
(51980, 389, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(51981, 389, 'h_sec7_road_map_1_description', 'Запущены AR парки “Крейсер «Аврора»” и «поместье Алтун» в России, AR парк  «Крепость Бастилия» во Франции. Проект в TOP 10 мировых стартапов на «Futur en Seine» (Париж, Франция).'),
(51982, 389, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(51983, 389, 'h_sec7_road_map_2_year', '2016'),
(51984, 389, '_h_sec7_road_map_2_year', 'field_59f50a9613a11'),
(51985, 389, 'h_sec7_road_map_2_open_or_close', '1'),
(51986, 389, '_h_sec7_road_map_2_open_or_close', 'field_59f50b06ae597'),
(51987, 389, 'h_sec7_road_map_2_description', 'Запущены AR парки «Форум Помпеи» в Италии и «Дорога жизни»  в России. Начата разработка собственной технологии компьютерного зрения, мы начали развивать собственную систему Computer Vision.'),
(51988, 389, '_h_sec7_road_map_2_description', 'field_59f50aaa13a12'),
(51989, 389, 'h_sec7_road_map_3_year', '2017'),
(51990, 389, '_h_sec7_road_map_3_year', 'field_59f50a9613a11'),
(51991, 389, 'h_sec7_road_map_3_open_or_close', '1'),
(51992, 389, '_h_sec7_road_map_3_open_or_close', 'field_59f50b06ae597'),
(51993, 389, 'h_sec7_road_map_3_description', 'Действует  8 парков дополненной реальности в 6 странах мира. Разрабатывается собственная AR платформа для дистанционного позиционирования и управления объектами дополненной реальности'),
(51994, 389, '_h_sec7_road_map_3_description', 'field_59f50aaa13a12'),
(51995, 389, 'h_sec7_road_map_4_year', '2017'),
(51996, 389, '_h_sec7_road_map_4_year', 'field_59f50a9613a11'),
