(52548, 391, '_h_sec7_road_map_0_open_or_close', 'field_59f50b06ae597'),
(52549, 391, 'h_sec7_road_map_0_description', 'Launched first outdoor AR park - \"Ludza Castle.\" It increased by 30% the flow of tourists in the region, attracting more than 60,000 tourists/year. Microsoft Seed Fund grant, Accelerations: Intel, Google, Faber Novel. Top 50  russian  startups with  highest rating AAA'),
(52550, 391, '_h_sec7_road_map_0_description', 'field_59f50aaa13a12'),
(52551, 391, 'h_sec7_road_map_1_year', '2015'),
(52552, 391, '_h_sec7_road_map_1_year', 'field_59f50a9613a11'),
(52553, 391, 'h_sec7_road_map_1_open_or_close', '1'),
(52554, 391, '_h_sec7_road_map_1_open_or_close', 'field_59f50b06ae597'),
(52555, 391, 'h_sec7_road_map_1_description', 'Launched Aurora and Altun AR parks at Russia, Bastille fortress AR park at France. TOP 10 world startups on “Futur en Seine”, Paris, France.'),
(52556, 391, '_h_sec7_road_map_1_description', 'field_59f50aaa13a12'),
(52557, 391, 'h_sec7_road_map_2_year', '2016'),
