(52561, 391, 'h_sec7_road_map_2_description', 'Launched AR parks the Forum PompeII at Italy  and Ice Road at Russia , we began to develop our own Computer Vision system.'),
(52562, 391, '_h_sec7_road_map_2_description', 'field_59f50aaa13a12'),
(52563, 391, 'h_sec7_road_map_3_year', '2017'),
(52564, 391, '_h_sec7_road_map_3_year', 'field_59f50a9613a11'),
(52565, 391, 'h_sec7_road_map_3_open_or_close', '1'),
(52566, 391, '_h_sec7_road_map_3_open_or_close', 'field_59f50b06ae597'),
(52567, 391, 'h_sec7_road_map_3_description', 'We already have launched  8 AR outdoor parks in 6 countries: Russia, France, Latvia, Italy, Estonia and Bulgaria.Started to develop our own augmented reality platform to remotely positioning and  management digital assets .'),
(52568, 391, '_h_sec7_road_map_3_description', 'field_59f50aaa13a12'),
