(52916, 393, '_home_banner_top_buttons', 'field_59f4ea9061b70'),
(52917, 393, 'home_banner_heading', '是将虚拟和现实世界结合在单一生态系统中的信息空间。'),
(52918, 393, '_home_banner_heading', 'field_59f4eb4e6b25d'),
(52919, 393, 'home_banner_sub_heading', '它基于在地面创建带有自然标记的增强现实层连接的平台，<br>用于远程定位和虚拟内容管理。'),
(52920, 393, '_home_banner_sub_heading', 'field_59f4eb606b25e'),
(52921, 393, 'home_banner_notes_beside_the_countdown', 'Arcona Token   -  1 ARN = 1 USD\r\nArcona token will be used for the purchase of all digital goods and services within the ecosystem. '),
(52922, 393, '_home_banner_notes_beside_the_countdown', 'field_59f4eb726b25f'),
