(54673, 396, '_h_sec6_heading', 'field_59f5ab312cd86'),
(54674, 396, 'h_sec6_image', '158'),
(54675, 396, '_h_sec6_image', 'field_59f5ab5b2cd87'),
(54676, 396, 'h_sec6_top_text_content', 'The Arcona platform is being developed by the professional team of <a href=\"//www.piligrimxxi.com/presskit\" target=\"_blank\">PiligrimXXI</a>. Since 2015, PiligrimXXI has been actively investing its own funds to research the field of distributed GIS system, Augmented Reality technologies, 3D simulations, Computer vision and Artificial Intelligence and is the first Russian IT start-up operating in the international augmented reality market in the travel industry. \r\n\r\nPiligrimXXI has given tourists the opportunity to combine real travel and time travel. We have launched the world’s first augmented reality parks in a total of 8 parks in 6 countries. Using a smartphone and AR headset, travelers can see with their own eyes the architectural wonders of the past and witness historical events in real time. \r\n\r\n<h3 class=\"headingtype2 text-center\">We Were Assisted by the Following Great Companies</h3>'),
(54672, 396, 'h_sec6_heading', 'WHO IF NOT US?'),
(54671, 396, '_h_sec5_section_id_with_hash_to_scroll', 'field_59fb499393fd8'),
(54670, 396, 'h_sec5_section_id_with_hash_to_scroll', '#sectionElaven'),
(54669, 396, '_h_sec5_subscribe_button_text', 'field_59fb496893fd7'),
(54668, 396, 'h_sec5_subscribe_button_text', 'Subscribe Now'),
(54667, 396, '_h_sec5_image', 'field_59f5074750065'),
(54666, 396, 'h_sec5_image', '115'),
(54665, 396, '_h_sec5_text_content', 'field_59f506dd50064'),
(54664, 396, 'h_sec5_text_content', '<div class=\"coins\">\r\n<img src=\"/wp-content/uploads/2017/11/coin1.png\" alt=\"\">\r\n<img src=\"/wp-content/uploads/2017/11/coin2.png\" alt=\"\">\r\n</div>\r\n<p class=\"type1\">Arcona will be introduced in the first quarter of 2018</p>\r\n<p class=\"type2\">The arcona token help you to purchase digital lands and other digital assets.</p>\r\n<p class=\"type2\">You can get arcona as a reward for performing tasks set by the Arcona system.</p>\r\n<p class=\"type3\">Total emission — 100 000 000 arconas</p>\r\n<p class=\"type4\">DISTRIBUTION OF TOKENS</p>'),
(54663, 396, '_h_sec5_heading', 'field_59f5069450063'),
(54662, 396, 'h_sec5_heading', 'ARCONA TOKEN SALE'),
(54660, 396, 'h_sec4_image', '318'),
