(54631, 396, '_h_sec2_heading', 'field_59f4fb467be91'),
(54628, 396, 'h_sec1_youtube_video_embedcode', '<iframe height=\"100%\" width=\"100%\" allowfullscreen=\"\" frameborder=\"0\" title=\"External YouTube\" src=\"//www.youtube.com/embed/s0ERldL5hEE?wmode=transparent&amp;autoplay=0&amp;theme=dark&amp;controls=0&amp;autohide=0&amp;loop=1&amp;showinfo=0&amp;rel=0&amp;playlist=s0ERldL5hEE&amp;enablejsapi=0\"></iframe>'),
(54627, 396, '_h_sec1_link_for_the_text_content', 'field_59f4f6a2924fd'),
(54626, 396, 'h_sec1_link_for_the_text_content', 'https://www.arcona.io/'),
(54625, 396, '_h_sec1_text_content', 'field_59f4f66e924fc'),
(54624, 396, 'h_sec1_text_content', 'The Arcona Ecosystem creates a Digital Land - a layer of Augmented Reality uniting the physical and virtual worlds into a single information environment perfectly linked to our real world. It is designed for everyday user interactive experience with augmented, virtual and mixed reality multimedia content in real world locations.'),
(54623, 396, '_h_sec1_heading', 'field_59f4f653924fb'),
(54622, 396, 'h_sec1_heading', 'AUGMENTED REALITY ECOSYSTEM'),
(54621, 396, '_home_banner_subscribe_button_title', 'field_59f4ebd36b260'),
(54620, 396, 'home_banner_subscribe_button_title', 'Buy arcona tokens NOW'),
(54619, 396, '_home_banner_notes_beside_the_countdown', 'field_59f4eb726b25f'),
(54618, 396, 'home_banner_notes_beside_the_countdown', 'Token Sale Start by 27.11.2017\r\nArcona Token Sale: 1 USD = 1 arcona\r\nArcona token will be used for the purchase of all digital goods and services within the ecosystem.'),
(54617, 396, '_home_banner_sub_heading', 'field_59f4eb606b25e'),
(54616, 396, 'home_banner_sub_heading', 'Buy Tokens Arcona - Вecome the Owner<br>of the New Digital Land</small>'),
